import{H as e,Q as t,ht as n,nt as r,tt as i}from"./chunks/framework.qcK96eCy.js";var a=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"wg-easy-mcp","text":"Your WireGuard VPN, spoken to","tagline":"An MCP server for wg-easy v15: list, create and revoke VPN clients, pull configs and QR codes, and read server status — from Claude, Codex or any MCP client.","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Tools reference","link":"/reference/tools"},{"theme":"alt","text":"GitHub","link":"https://github.com/ni-c/wg-easy-mcp"}]},"features":[{"title":"Eleven tools, one API","details":"Full client lifecycle over the wg-easy v15 REST API — including .conf files, QR codes and one-time download links — with partial updates that merge into the current client state instead of overwriting it."},{"title":"Runs anywhere stdio does","details":"A single npx command, a Claude Desktop JSON block, a Codex TOML entry or a multi-arch container image with an SBOM and build provenance."},{"title":"A context-sized subset","details":"WG_EASY_READ_ONLY=true registers the read tools and nothing else. WG_EASY_ALLOW_TOOLS cuts finer — essential for a curated eight, your own comma-separated list, or a whole family with list_* — and WG_EASY_DENY_TOOLS subtracts. Whatever is filtered out does not exist on the protocol rather than failing when called, and a name that matches no tool stops the server at startup instead of quietly going missing."},{"title":"Safe by default","details":"Creating, changing or deleting a client, and issuing a one-time configuration link, ask a person first through MCP elicitation — a dialog the model cannot answer on its behalf, falling back to a token bound to the exact target where the client cannot show one. Admin secrets are redacted, upstream content is marked untrusted, and relaxed TLS is scoped to one connection instead of the whole process."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788380634000}`),o={name:`index.md`};function s(e,a,o,s,c,l){return n(),i(`div`,null,[...a[0]||=[t(`figure`,{class:`diagram`},[t(`svg`,{viewBox:`0 0 760 250`,role:`img`,"aria-labelledby":`arch-title arch-desc`},[t(`title`,{id:`arch-title`},`wg-easy-mcp architecture`),t(`desc`,{id:`arch-desc`},`An MCP client speaks stdio to wg-easy-mcp, which calls the wg-easy REST API over HTTPS with Basic Authentication; wg-easy configures the WireGuard interface.`),t(`defs`,null,[t(`marker`,{id:`arrow`,markerWidth:`9`,markerHeight:`9`,refX:`8`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L0,6 L8,3 z`})]),t(`marker`,{id:`arrow-accent`,class:`accent`,markerWidth:`9`,markerHeight:`9`,refX:`8`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L0,6 L8,3 z`})])]),t(`rect`,{class:`node`,x:`14`,y:`62`,width:`164`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`96`,y:`93`,"text-anchor":`middle`},`MCP client`),t(`text`,{class:`label-muted`,x:`96`,y:`113`,"text-anchor":`middle`},`Claude, Codex, Inspector`),t(`rect`,{class:`node-accent`,x:`248`,y:`62`,width:`180`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`338`,y:`93`,"text-anchor":`middle`},`wg-easy-mcp`),t(`text`,{class:`label-muted`,x:`338`,y:`113`,"text-anchor":`middle`},`11 tools, zod-validated`),t(`rect`,{class:`node`,x:`498`,y:`62`,width:`164`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`580`,y:`93`,"text-anchor":`middle`},`wg-easy v15`),t(`text`,{class:`label-muted`,x:`580`,y:`113`,"text-anchor":`middle`},`REST API :51821`),t(`rect`,{class:`node`,x:`498`,y:`178`,width:`164`,height:`54`,rx:`10`}),t(`text`,{class:`label-title`,x:`580`,y:`203`,"text-anchor":`middle`},`WireGuard`),t(`text`,{class:`label-muted`,x:`580`,y:`221`,"text-anchor":`middle`},`wg0 interface`),t(`path`,{class:`edge-accent`,d:`M178,102 L242,102`,"marker-end":`url(#arrow-accent)`}),t(`text`,{class:`label-mono`,x:`210`,y:`90`,"text-anchor":`middle`},`stdio`),t(`path`,{class:`edge-accent`,d:`M428,102 L492,102`,"marker-end":`url(#arrow-accent)`}),t(`text`,{class:`label-mono`,x:`460`,y:`90`,"text-anchor":`middle`},`HTTPS`),t(`text`,{class:`label-muted`,x:`460`,y:`126`,"text-anchor":`middle`},`Basic Auth`),t(`path`,{class:`edge edge-dashed`,d:`M580,142 L580,172`,"marker-end":`url(#arrow)`}),t(`text`,{class:`label-muted`,x:`338`,y:`164`,"text-anchor":`middle`},`asks a person · redaction · response budget`)]),t(`figcaption`,null,`The server holds no state beyond short-lived approvals; wg-easy remains the source of truth.`)],-1),r(`<h2 id="running-it-elsewhere" tabindex="-1">Running it elsewhere <a class="header-anchor" href="#running-it-elsewhere" aria-label="Permalink to “Running it elsewhere”">​</a></h2><p>A client that cannot spawn a local process — ChatGPT connectors, Claude on the web, Cursor, LibreChat — cannot start wg-easy-mcp the way Claude Code does. <a href="https://mcp-hub.ni-c.de" target="_blank" rel="noreferrer">mcp-hub</a> is the bridge: one container serves many stdio MCP servers over Streamable HTTP, with an OAuth 2.1 login behind a single password and long-lived tokens for the clients that cannot do OAuth. Its <code>/hub</code> endpoint puts every server behind six meta-tools, so one connector reaches all of them without N×tool schemas in the model&#39;s context, and it speaks both protocol revisions — a question this server asks travels through it to the person at the far end instead of ending at the gateway.</p><p>Its configuration is Claude Code&#39;s <code>mcpServers</code> format, so the entry you already have is the entry it takes: <a href="/guide/clients#through-mcp-hub">Through mcp-hub</a>.</p>`,3)]])}var c=e(o,[[`render`,s]]);export{a as __pageData,c as default};